import{_ as s,O as a,o,c as i,a as r,i as l,f as n}from"./chunks/framework.fmIt2z2h.js";const h=JSON.parse('{"title":"D.12　宗教、文明比较与关系性知识","description":"","frontmatter":{"title":"D.12　宗教、文明比较与关系性知识","xkChars":744,"xkLessons":{"D.12":{"title":"D.12　宗教、文明比较与关系性知识","lead":"理解一种知识，并不自动取得公开、再用或代表它所属群体的权力。比较宗教、文明与关系性知识，应先确定具体文本、制度、实践和任务，既尊重保护边界，也保留具体效果与安全的检验。","explanation":["原文定位：第4705—4720行；原文锚点 section-d-12；短引文：‘知识可被定位、可以公开、允许再用和有权代表来源群体，是不同资格。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","希腊哲学、犹太教与基督教、伊斯兰思想、南亚传统、跨文化佛教、非洲思想、原住民知识、拉美解放思想以及东南亚和太平洋经验，不是有统一意愿的文明个人。把文明写成它想怎样、它必然怎样，会把内部异质、历史变化与政治权力混成一个主语。应具体说明讨论的是哪项文本、哪一机构、谁的实践与什么时期。","文本教义、制度规则、个人信仰、国家权力、改革运动和生活实践各有材料。一个教义命题不自动说明所有信徒怎样生活，国家行动不代表所有宗教成员意愿，改革文本也不保证制度已全面改变。局部制度改善与剩余排除可以同时存在，不能把比较写成一个文明总排名。","关系性知识可能包括细致的环境观察、技能和责任安排。技能在特定任务中确实有效，不要求研究者先穷尽它的全部机理；但成功技能也不能为伴随的每一种宇宙论解释提供通用证明。应分别核任务表现、形成与传承条件、机制解释和规范意义，不以一种成功替所有主张结案。","宗教和哲学论证可以提供独立理解与规范价值，未必都要还原成经验预测。同时，道德、政治与经验主张仍按各自条件接受批评：经验效应需对应材料，规范主张需公开理由与受影响者位置，理解价值可讨论概念与生活意义。尊重一种传统不等于免除所有具体检验，也不等于必须先把它翻译成外部模型才算知识。","四种资格需要单独写清：知识是否可以定位、材料是否允许公开、特定使用是否获许可、某人是否有权代表来源群体。知道地点或理解术语只解决有限认识问题；保护性不公开也不证明知识不存在。外部研究者不能从学懂一个概念推导出传播敏感材料或替群体作决定的权力。","翻译的充分性取决于任务。为了完成一种航行方位交流，若若干术语能稳定对接，可以支持该任务中的合作；对于关系责任、仪式或生活意义，仍可能有不能由同一词汇直接对齐的部分。这不是全然无法理解，也不是已经完整等同。应明确翻译保留哪些区别，哪些用途需要再次解释和确认。","原文航行例让两方同时保留有限成果与边界。本地实践能可靠完成某类任务，外来模型能解释部分航迹，两者可以互查误差；方程明确不产生生活决定权，文化身份也不使具体安全或效果免检。这里的例子是教学假设，不是对任一真实航海群体的性能评估或授权。","跨期可比性也应按具体题项和用途判断。某题更改问法或调查模式，可能使该题不能直接连接旧序列；若别的题有合格桥接依据，其趋势不因此全部失效。反过来，整份调查名字相同也不能保证每道题的含义和选择进入相同。局部差异应限制依赖它的结论，而不是自动清空所有材料。","同一次随机分配的后续随访增加时间信息，不增加独立试验次数。同一批对象的多期结果可能相关，不能按多项独立研究来计数或任意提高确定性。两期分别显著和不显著也不是时期差异的检验：需要直接比较效应变化，考虑标准误、相关性及设计，而不是比较两个标签。","有限技能和服务改善可以成立，个人议程、拒绝与救济权限仍须另评。帮助一项任务变得更好，不自动让服务者决定所有生活；服务对象尚缺治理权，也不要求否认已得到的有限帮助。要保留并行结论，避免把任何单一改进升级为全部权利问题已解决。","十三个入口依次是柏拉图亚里士多德斯多亚、犹太与基督传统、伊斯兰思想共同体、印度佛教印度教耆那教、佛教跨文化、世俗化改革复兴、非洲与Ubuntu、原住民关系性知识、拉美解放去殖民、文明翻译不可对齐、南亚种姓等级改革、东南亚自主历史，以及太平洋航海关系知识。入口不意味着各传统单一。最强反方担心尊重边界会使检验停止；回应是公开与代表资格不能从检验需要自动生成，而具体获得许可的主张仍可按合适标准批评。"],"distinctions":[{"leftTitle":"定位到知识","leftText":"能够辨认材料或知识所在。","rightTitle":"公开再用代表资格","rightText":"须分别有相应依据与许可，不能由理解自动获得。"},{"leftTitle":"技能有限有效","leftText":"在指定任务中表现可支持。","rightTitle":"所有解释都真","rightText":"伴随的机制或宇宙论仍各需材料与论证。"},{"leftTitle":"某任务翻译充分","leftText":"某些区别足以完成当前合作。","rightTitle":"全面意义等同","rightText":"关系责任等其他用途可能仍有不可对齐部分。"},{"leftTitle":"同次试验多期随访","leftText":"增加时间与轨迹信息。","rightTitle":"多次独立试验","rightText":"需独立设计与信息结构，不能靠次数标签增加。"},{"leftTitle":"某期显著另期不显著","leftText":"各自估计相对各自不确定性的判断。","rightTitle":"时期效应差异显著","rightText":"须直接检验差值并考虑相关与设计。"}],"boundaries":["不把文明、宗教或文化群体当作有单一意愿的人格主体。","不公开敏感社区知识，不从公共术语理解推导再用或代表授权。","保护文化与检验具体安全效果可以并行，身份不提供免检，也不将模型明确性变为决定权。","所述航行与跨期数字都是教学构造，未开展实际航行、调查或试验。","真实标签案例只证实发布方规则说明，不声称所有社区都采纳或已经有效保护。"],"questions":["为什么技能有效不要求先识别全部机理？","四种知识资格为何不能合并？","多次随访增加什么、不增加什么？","部分改革与剩余排除能否同时成立？"],"diagramPath":"/reading-assets/S-D-12/figures/section-d-12.png","caseLinks":[{"title":"真实协议设计：Local Contexts的TK标签","href":"https://localcontexts.org/labels/traditional-knowledge-labels/"}],"caseNotes":[{"title":"真实协议设计：Local Contexts的TK标签","text":"Local Contexts官方TK Labels说明将来源、访问协议和使用许可分列；Permission Labels明确其他用途需直接与相关文化权威接洽。其TK Community Use Only页面进一步说明一些材料通常仅在家庭、氏族或社区内流通，并由社区定制标签。这支持把可找到材料与获准再用分开，不说明任何读者已获得实际许可。","sourceLabel":"Local Contexts发布方官方协议说明","sourceUrl":"https://localcontexts.org/labels/traditional-knowledge-labels/","sourceLocator":"TK Labels导语第2—3段、Provenance/Protocol/Permission三类说明，尤Permission Labels行53—54；另见TK Community Use Only的Why use、Template Text及How to use","boundary":"核官方规则与模板的存在，不声称具体社区实施成功，不取用受限制材料，不代定谁有权代表群体。","href":"https://localcontexts.org/labels/traditional-knowledge-labels/"}],"sourceRefs":[{"section":"D.12","start_line":4705,"end_line":4720,"startLine":4705,"endLine":4720}],"outputId":"section-d-12","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["限定文本制度信仰国家改革实践的具体对象、时期与发言位置。","把技能效果、机制解释、宇宙论及规范理解分别评价，不要求全部机理先明也不无限扩张。","分别核定位、公开、再用、代表四种资格，保护性不公开不记为不存在。","说明翻译对何任务足够及何处仍不对齐，双向检查误差而不产生生活控制权。","跨期按题项核桥接，同一试验随访不重复计独立试验，显著性差异需直接检验。"],"teachingExamples":[{"title":"原文教学例展开：技能与模型互校","text":"假想某社区方法稳定完成一类航行任务，外来模型解释其中部分航迹。双方可在获许可的范围比较误差、任务条件和各自限制；不能由模型方程清晰就把生活决策权交给外来者，也不能以传统身份拒绝所有具体安全核查。","assumptions":"沿原文假想，不是真实航海史或安全评估。","boundary":"没有给出现实航行建议，不推断任何群体全部知识或信仰为真。"},{"title":"教学构造：一个题项改了，不取消所有趋势","text":"假想调查题A从满意度改成安全感，题B保持相同定义且有适当桥接依据。A的两期值不能直接接成同一趋势；B仍可按桥接支持程度分析。应局部限制A的依赖结论，而非说整份调查所有跨期问题都无意义。","assumptions":"题目与桥接条件均设定，非实际调查结果。","boundary":"真实桥接是否足够须检查问法模式样本与适用目标，不能只看题目同名。"},{"title":"数学教学构造：显著与不显著不等于效应不同","text":"设两期效应估计均为0.20，正态近似标准误分别0.09、0.12。各自z约2.22与1.67，按双侧5%阈值1.96，一期显著另期不显著；但点估计差为0。在差值标准误为正且估计适当的条件下，差值z为0，不能据两标签宣称效应已经改变。","assumptions":"数值和正态检验均为教学模型，未计算真实研究统计量。","boundary":"真实相关随访的差值标准误需协方差等设计信息；此例不假设真实随访独立。"},{"title":"教学构造：三次随访仍是一项随机试验","text":"假想一次随机分配后在第1、6、12个月随访。可研究时间变化，但不能把三个报告当三次独立随机试验；失访和测量变化也须逐期核。服务改善与参与者能否拒绝、救济或主导议程另行判断。","assumptions":"月份与研究均构造。","boundary":"不实际估计任何干预效果，不将随访增加的信息视为零，只拒绝错误独立计数。"}],"counterexamples":[{"identity":"source_counterexample","text":"这项知识没有公开，所以它不存在，也没有值得理解的内容。","effect":"保护性不公开与不存在不同，公开资格须独立核。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"我已准确翻译术语，所以可以发表敏感内容并代表群体。","effect":"理解、公开、再用和代表不是同一资格。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"第一期显著、第二期不显著，所以两期效应有显著差异。","effect":"须直接检验效应差；相同点估计不同标准误就是反例。","sourceIds":["theory"]}],"questionAnswers":[{"question":"为什么技能有效不要求先识别全部机理？","answer":"限定任务表现可以得到直接支持，但这不替伴随机制或宇宙论的每项解释作证。","basis":"本节原文及上述公开推导"},{"question":"四种知识资格为何不能合并？","answer":"定位认识、公开传播、特定再用和群体代表涉及不同权限与受影响者。","basis":"本节原文及上述公开推导"},{"question":"多次随访增加什么、不增加什么？","answer":"增加时间与轨迹信息，不自动增加独立随机试验次数。","basis":"本节原文及上述公开推导"},{"question":"部分改革与剩余排除能否同时成立？","answer":"可以，各有具体对象和证据，不需要给整个文明一个胜负总排名。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-12/figures/section-d-12.png","alt":"文本／制度／信仰，国家／改革／实践，不合成文明人格；技能有限有效，机理可仍未全明，宇宙论不因此全真；四种资格分别核，定位／公开，再用／代表；翻译按任务判，局部充分，仍可有不可对齐；跨期逐题核桥接，多随访≠多独立试验，显著标签≠差值检验；有限改善可成立，议程拒绝救济另判，不做文明总排名。作者依D.12绘制；航行调查与检验数值均为教学构造，未使用限制知识。","caption":"作者依D.12绘制；航行调查与检验数值均为教学构造，未使用限制知识。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换具体用途、许可资格、题项桥接及随访相关条件，显示哪些结论可保留。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"现实协议把来源访问和许可分开，适合展示资格差异；不把模板存在升级为实际授权或普遍成效。"},"openQuestions":["未取得12.01—12.13全部原研究与社区材料，不复原完整文明史或代表任何群体。","TK标签案例只核官方设计与说明，未核具体社区实际采用和保护成效。"],"taskId":"S-D-12","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4705—4720行；每节精确范围见sourceRefs","claim_support":["D.12：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"localcontexts-labels","title":"TK Labels","url":"https://localcontexts.org/labels/traditional-knowledge-labels/","source_type":"primary","version_or_date":"页面未标发布日期","locator":"导语第2—3段；三分类说明；Permission Labels行53—54","claim_support":["来源、访问协议、许可分列；其他用途需直接接洽相关文化权威"],"limits":["只证实设计和规则说明，不证明实际授权或所有社区实施成效。"],"access_status":"partially_read"},{"id":"localcontexts-community","title":"TK Community Use Only","url":"https://localcontexts.org/label/tk-community-use-only/","source_type":"primary","version_or_date":"页面未标发布日期","locator":"Why use this Label两段；Template Text两段；How to use首段（行9—17）","claim_support":["通常社区内部流通条件及标签由社区选择定制"],"limits":["未使用任何限制材料，不判断特定授权或实施效果。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-12/lecture.md","sourcesPath":"/reading-assets/S-D-12/sources.json","sourceSlicePath":"/reading-assets/S-D-12/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-12/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-12.md","filePath":"theory/appendix-d/d-12.md"}'),c={name:"theory/appendix-d/d-12.md"};function d(u,e,p,m,x,_){const t=a("SectionLesson");return o(),i("div",null,[e[0]||(e[0]=r('<div class="theory-source"><h1 id="section-d-12" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.12</span><span class="xk-num__gap">　</span></span>宗教、文明比较与关系性知识 <a class="header-anchor" href="#section-d-12" aria-label="Permalink to &quot;D.12　宗教、文明比较与关系性知识 {#section-d-12}&quot;">​</a></h1><p>正文连接：§2.7；§5.10；§7；§10；§16.15。研究入口：12.01—12.13。</p><p>希腊哲学、犹太教与基督教、伊斯兰思想、南亚诸传统、跨文化佛教、世俗化、非洲思想、原住民知识、拉美解放思想及东南亚、太平洋经验，不是一个个具有统一意愿的文明主体。文本教义、制度规则、个人信仰、国家权力、改革运动与生活实践须分别保留。</p><p>关系性知识可以包含细致的环境观察、技能和责任安排；宗教或哲学论证也可以产生独立的理解与规范价值。真实技能的有效性不要求研究者先识别全部机理，但也不能凭成功技能证明其中每一种宇宙论解释。道德、政治和经验主张按各自条件接受批评。</p><p>知识可被定位、可以公开、允许再用和有权代表来源群体，是不同资格。保护性不公开不等知识不存在；外部研究者理解一种术语，也不因此取得发表敏感材料或代表群体决定的权力。翻译可以对某一任务充分，同时对另一任务保留不可对齐的部分。</p><p>教学例：某社区的航行实践可靠地帮助完成一类任务，外来模型也能解释部分航迹。双方可以交流并检查各自误差；外来模型不因方程明确就取得生活决定权，本地方法也不因文化身份而免于具体安全与效果核查。局部制度改革与剩余排除可以同时存在，不把文明比较写成总排名。</p><p>跨期可比性属于具体题项和用途。一次调查的某题改变问法或模式，可以限制该题直接接线，同时保留其他有桥接依据的趋势。同一次随机分配的后续随访增加时间信息，不增加独立试验次数；两期分别显著与不显著，也不代替时期差异检验。有限技能与服务改善可以成立，个人议程、拒绝和救济权限另行评价。</p><p>专题定位：12.01 希腊哲学：柏拉图、亚里士多德、斯多亚传统；12.02 犹太教与基督教传统；12.03 伊斯兰思想与政治共同体；12.04 印度思想：佛教、印度教与耆那教等；12.05 佛教的跨文化传播；12.06 世俗化、宗教改革与宗教复兴；12.07 非洲思想与 Ubuntu 等传统；12.08 原住民与关系性知识；12.09 拉丁美洲解放思想与去殖民批评；12.10 文明比较与翻译不可对齐处；12.11 南亚种姓、社会等级与平等改革思想；12.12 东南亚社会的自主历史与思想实践；12.13 太平洋岛屿的社会、航海与关系性知识。</p></div>',1)),l(t,{section:"D.12"}),e[1]||(e[1]=n("div",{class:"theory-source"},null,-1))])}const g=s(c,[["render",d]]);export{h as __pageData,g as default};
